function closeNav(){document.body.classList.remove('nav-open');document.getElementById('navToggle').setAttribute('aria-expanded','false')}
document.getElementById('navToggle').onclick=()=>{let open=document.body.classList.toggle('nav-open');document.getElementById('navToggle').setAttribute('aria-expanded',String(open))};document.querySelector('.navbackdrop').onclick=closeNav;document.querySelector('aside').addEventListener('click',e=>{if(e.target.closest('button')){closeNav();window.scrollTo(0,0)}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeNav();closeModal()}});
function wrapTables(){document.querySelectorAll('table').forEach(t=>{if(t.parentElement.classList.contains('table-scroll'))return;let w=document.createElement('div');w.className='table-scroll';w.tabIndex=0;w.setAttribute('role','region');w.setAttribute('aria-label','数据表格，可左右滑动');t.before(w);w.append(t)})}new MutationObserver(wrapTables).observe(document.body,{childList:true,subtree:true});wrapTables();
